-- 027_redefinicao_de_senha — password reset link generated by the admin (holetz/eclume#119).
--
-- The link carries a 32-byte secret (`secrets.token_urlsafe`) stored only as SHA-256, like the
-- session and the PAT; it is valid for 24 h and single-use. Generating another expires the account's pending ones, and deactivating
-- the account does too. `admin_id` says who generated it (it becomes null if the admin account goes).
-- No RLS and no GRANT to `eclume_app`, like `sessions`: only the connection role reads it.
CREATE TABLE password_resets (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash  text NOT NULL UNIQUE,
    admin_id    uuid REFERENCES admins (id) ON DELETE SET NULL,
    expires_at  timestamptz NOT NULL,
    used_at     timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX password_resets_user_idx ON password_resets (user_id);

-- Already covered by the ALTER DEFAULT PRIVILEGES of 006 (same migrator); repeated for clarity.
GRANT SELECT, INSERT, UPDATE, DELETE ON password_resets TO eclume_server;
